2559	// Return Levenshtein distance between two strings.
2560	// (adapted from http://rosettacode.org/wiki/Levenshtein_distance#C)
2561	int gmic::_levenshtein(const char *const s, const char *const t,
2562	                       CImg<int>& d, const int i, const int j) {
2563	  const int ls = d.width() - 1, lt = d.height() - 1;
2564	  if (d(i,j)>=0) return d(i,j);
2565	  int x;
2566	  if (i==ls) x = lt - j;
2567	  else if (j==lt) x = ls - i;
2568	  else if (s[i]==t[j]) x = _levenshtein(s,t,d,i + 1,j + 1);
2569	  else {
2570	    x = _levenshtein(s,t,d,i + 1,j + 1);
2571	    int y;
2572	    if ((y=_levenshtein(s,t,d,i,j + 1))<x) x = y;
2573	    if ((y=_levenshtein(s,t,d,i + 1,j))<x) x = y;
2574	    ++x;
2575	  }
2576	  return d(i,j) = x;
2577	}
