2579	int gmic::levenshtein(const char *const s, const char *const t) {
2580	  const char *const ns = s?s:"", *const nt = t?t:"";
2581	  const int ls = (int)std::strlen(ns), lt = (int)std::strlen(nt);
2582	  if (!ls) return lt; else if (!lt) return ls;
2583	  CImg<int> d(1 + ls,1 + lt,1,1,-1);
2584	  return _levenshtein(ns,nt,d,0,0);
2585	}
